window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3494aaadaa8e8a3b"]={"versions": [{"id": "FIG-3494aaadaa8e8a3b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene des AUTOSAR-Metamodells). Das Diagramm veranschaulicht ein partiell modifiziertes AUTOSAR-Modell im Kontext des modellbasierten Datenaustauschs und der Werkzeug-Interoperabilität (Modell-Diff / Änderungserkennung zwischen AUTOSAR-Tools). Neu hinzugekommene bzw. betroffene Modellinstanzen sind farblich hervorgehoben (grün).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt folgende Instanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>:ARPackage</code> (uuid = \"6\", shortName = \"OEM\", grün markiert): Aggregiert über die Kompositionsrolle <code>+element</code> drei untergeordnete Elemente:</li>\n<li><code>:ApplicationPrimitiveDataType</code> (shortName = \"velocityType\", neutral/beige)</li>\n<li><code>:SenderReceiverInterface</code> (shortName = \"interface\", isService = false, grün markiert)</li>\n<li><code>ApplicationPrimitiveDataType : ApplicationPrimitiveDataType</code> (shortName = \"Boolean\", grün markiert)</li>\n<li><code>:ApplicationPrimitiveDataType</code> (\"velocityType\"): Aggregiert über <code>+invalidValue</code> eine Instanz <code>:NumericalValueSpecification</code> (value = 10000) sowie über <code>+displayFormat</code> eine Instanz <code>:DisplayFormatString</code> (value = \"%f6.2\").</li>\n<li><code>:SenderReceiverInterface</code> (\"interface\"): Aggregiert über die Rolle <code>+dataElement</code> zwei Datenprototypen:</li>\n<li><code>:VariableDataPrototype</code> (shortName = \"velocity\", beige), dessen Typ-Referenz <code>+type</code> auf <code>:ApplicationPrimitiveDataType</code> (\"velocityType\") verweist.</li>\n<li><code>:VariableDataPrototype</code> (shortName = \"buttonPressed\", grün markiert), dessen Komposition vom Interface ausgeht und dessen Typ-Referenz <code>+type</code> auf <code>:ApplicationPrimitiveDataType</code> (\"Boolean\") verweist.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm zur Repräsentation einer Modellinstanz-Struktur. Es bildet keinen dynamischen Sequenz- oder Laufzeitablauf ab, sondern den strukturellen Zustand eines AUTOSAR-M1-Modells zur Differenz- und Versionsanalyse in Interoperabilitäts-Tools.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als illustratives Beispiel in AUTOSAR_TR_InteroperabilityOfAutosarTools für Algorithmen zur Erkennung von Modelländerungen (Diff/Merge). Es verdeutlicht, dass das Hinzufügen neuer Elemente (<code>VariableDataPrototype</code> \"buttonPressed\", Datentyp \"Boolean\") auch die übergeordneten Container (<code>ARPackage</code> \"OEM\", <code>SenderReceiverInterface</code> \"interface\") als modifiziert kennzeichnet, da sich deren Aggregationen (<code>+element</code>, <code>+dataElement</code>) verändert haben.</p>"}, {"id": "FIG-66a6f95bc6e513e1", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzebene des AUTOSAR-Metamodells). Das Diagramm veranschaulicht ein partiell modifiziertes AUTOSAR-Modell im Kontext des modellbasierten Datenaustauschs und der Werkzeug-Interoperabilität (Modell-Diff / Änderungserkennung zwischen AUTOSAR-Tools). Neu hinzugekommene bzw. betroffene Modellinstanzen sind farblich hervorgehoben (grün).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt folgende Instanzen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>:ARPackage</code> (uuid = \"6\", shortName = \"OEM\", grün markiert): Aggregiert über die Kompositionsrolle <code>+element</code> drei untergeordnete Elemente:</li>\n<li><code>:ApplicationPrimitiveDataType</code> (shortName = \"velocityType\", neutral/beige)</li>\n<li><code>:SenderReceiverInterface</code> (shortName = \"interface\", isService = false, grün markiert)</li>\n<li><code>ApplicationPrimitiveDataType : ApplicationPrimitiveDataType</code> (shortName = \"Boolean\", grün markiert)</li>\n<li><code>:ApplicationPrimitiveDataType</code> (\"velocityType\"): Aggregiert über <code>+invalidValue</code> eine Instanz <code>:NumericalValueSpecification</code> (value = 10000) sowie über <code>+displayFormat</code> eine Instanz <code>:DisplayFormatString</code> (value = \"%f6.2\").</li>\n<li><code>:SenderReceiverInterface</code> (\"interface\"): Aggregiert über die Rolle <code>+dataElement</code> zwei Datenprototypen:</li>\n<li><code>:VariableDataPrototype</code> (shortName = \"velocity\", beige), dessen Typ-Referenz <code>+type</code> auf <code>:ApplicationPrimitiveDataType</code> (\"velocityType\") verweist.</li>\n<li><code>:VariableDataPrototype</code> (shortName = \"buttonPressed\", grün markiert), dessen Komposition vom Interface ausgeht und dessen Typ-Referenz <code>+type</code> auf <code>:ApplicationPrimitiveDataType</code> (\"Boolean\") verweist.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm zur Repräsentation einer Modellinstanz-Struktur. Es bildet keinen dynamischen Sequenz- oder Laufzeitablauf ab, sondern den strukturellen Zustand eines AUTOSAR-M1-Modells zur Differenz- und Versionsanalyse in Interoperabilitäts-Tools.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als illustratives Beispiel in AUTOSAR_TR_InteroperabilityOfAutosarTools für Algorithmen zur Erkennung von Modelländerungen (Diff/Merge). Es verdeutlicht, dass das Hinzufügen neuer Elemente (<code>VariableDataPrototype</code> \"buttonPressed\", Datentyp \"Boolean\") auch die übergeordneten Container (<code>ARPackage</code> \"OEM\", <code>SenderReceiverInterface</code> \"interface\") als modifiziert kennzeichnet, da sich deren Aggregationen (<code>+element</code>, <code>+dataElement</code>) verändert haben.</p>"}], "trans": [{"from": "FIG-3494aaadaa8e8a3b", "to": "FIG-66a6f95bc6e513e1", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
